                v=I[r][c]; r0=r
                while r<H and I[r][c]==v: r+=1
                runs.append(('v',c,r0,r-1,v))
            else: r+=1
    o=[row[:] for row in I]
    for t,p,s,e,v in runs:
        ext='in' if p==0 or s==H-1 else 'out'
        if t=='h':  # vertical run on a border row; horizontal ray along column extremes
            for cc in (s,e):
                d = -1 if cc==0 else +1
                rr=p
                while True:
                    rr += d
                    if not (0<=rr<H): break
                    if o[rr][cc]==v: break
                    elif o[rr][cc]==bg: o[rr][cc]=v
                    else: o[rr][cc]=4; break
        else:  # vertical run on a border col; horizontal ray along row extremes
            for rr in (s,e):
                d = -1 if p==0 else +1
                cc=p
                while True:
                    cc += d
                    if not (0<=cc<W): break
                    if o[rr][cc]==v: break
                    elif o[rr][cc]==bg: o[rr][cc]=v
                    else: o[rr][cc]=4; break
    return o

