# Hypothesis: flood fill from seeds through background, blocked by "wall" color (2 or 9-line / vertical 9s)
# In demo4: 2s act as walls (col0 rows2-3, col28 rows0-1); seeds 0 -> 4 after fill
def solve(g):
    h,w=len(g),len(g[0])
    from collections import deque
    # background = most common color
    bg=max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))
    out=[r[:] for r in g]
    seeds=[(i,j,c) for i,r in enumerate(g) for j,c in enumerate(r) if c!=bg and c not in (2,9)]
    wall=set()
    for i,r in enumerate(g):
        for j,c in enumerate(r):
            if c in (2,9): wall.add((i,j))
    q=deque(seeds)
    while q:
        i,j,_=q.popleft()
        if 0<=i<h and 0<=j<w and out[i][j]==bg:
            out[i][j]=0
            q.append((i-1,j)); q.append((i+1,j)); q.append((i,j-1)); q.append((i,j+1))
